/* warna bg icon burung */
.wdp-wrap-link{
    background: [00.35, 14/7/2022] Nomer 2ku: /* warna bg icon burung */
.wdp-wrap-link{
    background: #584A2F;
}

/* icon burung */
.wdp-link{
    color: #fbfbfb !important;
}

/* warna bg form */
.wdp-wrap-form {
    background: #584A2F;
}

/* tombol kirim */
.wdp-container-form input[type=submit] {
    color: #584A2F !important;
    background: #fbfbfb !important;
    font-family: alice !important;
}

/* warna bg ucapan */
.wdp-wrapper.wdp-golden ul.wdp-container-comments li.wdp-item-comment {

    background: #584A2F !important;
}

/* warna nama pemberi ucapan */
.wdp-wrapper.wdp-golden ul.wdp-container-comments li.wdp-item-comment .wdp-comment-content .wdp-comment-info a.wdp-commenter-name {

    color: #fbfbfb !important;
    font-family: alice;
    font-size: 16px !important;
    font-weight: 500;
}

/* warna tanggal ucapan */
.wdp-wrapper.wdp-golden ul.wdp-container-comments li.wdp-item-comment .wdp-comment-content .wdp-comment-info .wdp-comment-time {

    color: #ffffff !important;
    font-family: alice;
    font-size: 10px !important;
}

/* warna ucapan */
.wdp-wrapper.wdp-golden ul.wdp-container-comments li.wdp-item-comment .wdp-comment-content .wdp-comment-text p {

    color: #fbfbfb !important;
    font-family: alice;
    font-size: 14px !important;

}

/* warna konfirmasi kehadiran */
.wdp-wrapper.wdp-golden ul.wdp-container-comments li.wdp-item-comment .wdp-comment-content .wdp-comment-info .wdp-post-author {

    background-color: #FBFBFB;
    color: #584A2F
}

/* warna bg pagination */
.wdp-wrapper .wdp-holder {

    background: #584A2F !important;
}

/* warna kata sebelumnya */
.wdp-wrapper .wdp-holder a.jp-previous {

    color: #FBFBFB !important;
}

/* warna kata selanjutnya */
.wdp-wrapper .wdp-holder a.jp-next {

    color: #FBFBFB;
}

.wdp-wrapper .wdp-holder a.jp-current, .wdp-wrapper .wdp-holder a.jp-current:hover {

    color: #FBFBFB;
}

.wdp-wrapper.wdp-golden .wdp-holder a, .wdp-wrapper.wdp-golden .wdp-holder a:link, .wdp-wrapper.wdp-golden .wdp-holder a:visited {

    color: #FBFBFB !important;
}
